/* auto-generated by paperforge notation_registry.py — do not edit */
window.paperforgeNotation = {"farDelayMs": 500, "nearDelayMs": 200, "defsiteHlDelayMs": 120};
window.PAPERFORGE_NOTATION = {};
// No doc-gen4 bundle is published for this AINTLIB snapshot yet.  Defining an
