window.PAPERFORGE_LEAN_KNOWLS = Object.assign(
  window.PAPERFORGE_LEAN_KNOWLS || {},
  {}
);
window.PAPERFORGE_SECTION_SUMMARIES = {"sec-introduction": {"label": "Section 1", "title": "Introduction", "html": "<div class=\"para\">Buzzard and Verberkmoes proved that every stably uniform Tate Huber ring is sheafy and exhibited both uniform rings which are not stably uniform and uniform rings which are not sheafy <a href=\"#bib-BV\" class=\"xref\" title=\"Bibliographic Entry bib-BV\">[bib-BV]</a>.  Hansen and Kedlaya subsequently asked whether a uniform sheafy Huber ring must be stably uniform <a href=\"#bib-HK\" class=\"xref\" title=\"Bibliographic Entry bib-HK\">[bib-HK, Remark 3.16]</a>; this is also Question 7 of Kedlaya’s <em class=\"emphasis\">Nonarchimedean Scottish Book</em> <a href=\"#bib-Scottish\" class=\"xref\" title=\"Bibliographic Entry bib-Scottish\">[bib-Scottish]</a>.  We give a negative answer in two forms.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-introduction-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-conventions": {"label": "Section 2", "title": "Conventions and notation", "html": "<div class=\"para\">We follow Huber for Huber pairs, adic spectra, rational subsets, and rational localisation <a href=\"#bib-Huber94\" class=\"xref\" title=\"Bibliographic Entry bib-Huber94\">[bib-Huber94]</a>; the bounded-denominator language for strictness follows Buzzard–Verberkmoes <a href=\"#bib-BV\" class=\"xref\" title=\"Bibliographic Entry bib-BV\">[bib-BV]</a>, and the graph presentation is also discussed by Hansen–Kedlaya <a href=\"#bib-HK\" class=\"xref\" title=\"Bibliographic Entry bib-HK\">[bib-HK]</a>.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-conventions-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-the-global-ring": {"label": "Section 3", "title": "The global ring", "html": "<div class=\"para\">In this section we identify the finite-jet algebra with a concrete support subring and prove that it is a complete uniform domain.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-the-global-ring-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-a-nonuniform-rational-localization": {"label": "Section 4", "title": "A nonuniform rational localization", "html": "<div class=\"para\">We next compute the rational chart which witnesses the failure of stable uniformity.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-a-nonuniform-rational-localization-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-localization-of-the-milnor-square": {"label": "Section 5", "title": "Localization of the Milnor square", "html": "<div class=\"para\">We now prove that every rational localization preserves the defining pullback.  The argument is formulated entirely in terms of the chosen rings of definition.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-localization-of-the-milnor-square-2-1\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>"}, "sec-localization-of-the-milnor-square-graph-koszul-complexes-over-affinoid": {"label": "Subsection 5.1", "title": "Graph Koszul complexes over affinoid algebras", "html": "<div class=\"para logical\">\n<div class=\"para\">The following lemma will be used both at the noetherian comparison vertices and at the finite heads in <a href=\"#sec-rationally-reduced\" class=\"internal\" title=\"Section 7: A rationally stably reduced example\">Section 7</a>.  Let <span class=\"process-math\">\\(E\\)</span> be an affinoid <span class=\"process-math\">\\(k\\)</span>-algebra, choose a noetherian <span class=\"process-math\">\\(\\varpi\\)</span>-adically complete ring of definition <span class=\"process-math\">\\(E_0\\subset E\\text{,}\\)</span> and let <span class=\"process-math\">\\(f_1,\\dots,f_m,g\\in E_0\\)</span> generate the unit ideal in <span class=\"process-math\">\\(E\\text{.}\\)</span>  Put</div>\n<div class=\"displaymath process-math\" data-contains-math-knowls=\"./knowl/xref/sec-rationally-reduced.html\">\n\\begin{equation*}\nP_E=E\\langle T_1,\\dots,T_m\\rangle,\n\\qquad\nP_{E,0}=E_0\\langle T_1,\\dots,T_m\\rangle,\n\\end{equation*}\n</div>\n<div class=\"para\">and set <span class=\"process-math\">\\(r_i=gT_i-f_i\\text{.}\\)</span>\n</div>\n<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-localization-of-the-milnor-square-graph-koszul-complexes-over-affinoid-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-localization-of-the-milnor-square-the-graph-ideals-form-a": {"label": "Subsection 5.2", "title": "The graph ideals form a pullback", "html": "<div class=\"para logical\">\n<div class=\"para\">Fix a rational datum</div>\n<div class=\"displaymath process-math\">\n\\begin{equation*}\n\\alpha=(f_1,\\dots,f_m;g)\n\\end{equation*}\n</div>\n<div class=\"para\">in <span class=\"process-math\">\\(A\\text{.}\\)</span>  Multiplying all entries by a common power of <span class=\"process-math\">\\(\\varpi\\text{,}\\)</span> we assume <span class=\"process-math\">\\(f_1,\\dots,f_m,g\\in A_0\\text{.}\\)</span>  For <span class=\"process-math\">\\(E\\in\\{A,B,C,D\\}\\)</span> use the notation <span class=\"process-math\">\\(P_E\\text{,}\\)</span> <span class=\"process-math\">\\(P_{E,0}\\text{,}\\)</span> and <span class=\"process-math\">\\(d_{1,E}\\)</span> introduced above, and abbreviate the graph ideal <span class=\"process-math\">\\(J_{E,\\alpha}\\)</span> to <span class=\"process-math\">\\(J_E\\text{.}\\)</span>\n</div>\n<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-localization-of-the-milnor-square-the-graph-ideals-form-a-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-sheafiness": {"label": "Section 6", "title": "Sheafiness", "html": "<div class=\"para\">We isolate the elementary descent statement used to transfer sheafiness from the three comparison rings.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-sheafiness-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-rationally-reduced": {"label": "Section 7", "title": "A rationally stably reduced example", "html": "<div class=\"para\">The finite-jet construction above loses uniformity because separated completion creates a nilpotent.  We now give a second construction in which the bad rational localization is an integral domain.  The loss of uniformity is instead caused by an unbounded family of nonnilpotent power-bounded elements.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-rationally-reduced-2-1\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-rationally-reduced-the-weighted-parity-algebra": {"label": "Subsection 7.1", "title": "The weighted-parity algebra", "html": "<div class=\"para logical\">\n<div class=\"para\">Let <span class=\"process-math\">\\(I=\\mathbf N_{&gt;0}\\text{.}\\)</span>  For a finite-support multi-index <span class=\"process-math\">\\(\\nu=(\\nu_n)_{n\\in I}\\in\\mathbf N^{(I)}\\text{,}\\)</span> put</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\n\\omega(\\nu)=\\sum_{\\substack{n\\geq1\\\\ \\nu_n\\text{ odd}}} n.\\tag{7.1}\n\\end{equation}\n</div>\n<div class=\"para\">Consider the submonoid</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\nS=\\left\\{(a,\\nu)\\in\\mathbf N\\times\\mathbf N^{(I)}:\na\\geq\\omega(\\nu)\\right\\}.\\tag{7.2}\n\\end{equation}\n</div>\n<div class=\"para\">The inequality</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\n\\omega(\\nu+\\mu)\\leq\\omega(\\nu)+\\omega(\\mu)\\tag{7.3}\n\\end{equation}\n</div>\n<div class=\"para\">shows that <span class=\"process-math\">\\(S\\)</span> is closed under addition.  It is locally finite: a fixed element of <span class=\"process-math\">\\(S\\)</span> has only finitely many decompositions as a sum of two elements of <span class=\"process-math\">\\(S\\text{.}\\)</span>\n</div>\n<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-rationally-reduced-the-weighted-parity-algebra-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-rationally-reduced-a-reduced-nonuniform-rational-chart": {"label": "Subsection 7.2", "title": "A reduced nonuniform rational chart", "html": "<div class=\"para logical\">\n<div class=\"para\">The datum <span class=\"process-math\">\\((W;\\varpi)\\)</span> is a genuine rational datum: the ideal <span class=\"process-math\">\\((W,\\varpi)\\)</span> is open because <span class=\"process-math\">\\(\\varpi\\)</span> is a unit of <span class=\"process-math\">\\(\\mathcal A\\text{.}\\)</span>  Define the complete <span class=\"process-math\">\\(k^\\circ\\)</span>-algebra</div>\n<div class=\"displaymath process-math\" data-contains-math-knowls=\"./knowl/xref/eq-omega-subadditive.html\">\n\\begin{equation}\n\\mathcal B_0=\n\\left\\{\n\\sum_{\\substack{\\nu\\in\\mathbf N^{(I)},\\ d\\geq\\omega(\\nu)}}\nb_{d,\\nu}X^dU^\\nu:\nb_{d,\\nu}\\in\\varpi^{\\omega(\\nu)}k^\\circ,\n\\quad\n\\varpi^{-\\omega(\\nu)}b_{d,\\nu}\\longrightarrow0\n\\right\\},\\tag{7.12}\n\\end{equation}\n</div>\n<div class=\"para\">with norm</div>\n<div class=\"displaymath process-math\" data-contains-math-knowls=\"./knowl/xref/eq-omega-subadditive.html\">\n\\begin{equation}\n\\left\\lVert\\sum b_{d,\\nu}X^dU^\\nu\\right\\rVert_{\\mathrm{in}}\n=\\sup_{d,\\nu}|\\varpi|^{-\\omega(\\nu)}|b_{d,\\nu}|.\\tag{7.13}\n\\end{equation}\n</div>\n<div class=\"para\">The subadditivity <a href=\"#eq-omega-subadditive\" class=\"xref\" title=\"Equation 7.3\">(7.3)</a> shows that <span class=\"process-math\">\\(\\mathcal B_0\\)</span> is a ring.  Put <span class=\"process-math\">\\(\\mathcal B=\\mathcal B_0[1/\\varpi]\\text{.}\\)</span>\n</div>\n<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-rationally-reduced-a-reduced-nonuniform-rational-chart-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-rationally-reduced-small-perturbations-of-rational-data": {"label": "Subsection 7.3", "title": "Small perturbations of rational data", "html": "<div class=\"para\">The finite-head argument rests on the following elementary stability result.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-rationally-reduced-small-perturbations-of-rational-data-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-rationally-reduced-finite-head-rational-localization": {"label": "Subsection 7.4", "title": "Finite-head rational localization", "html": "<div class=\"para logical\">\n<div class=\"para\">Fix <span class=\"process-math\">\\(N\\geq1\\text{.}\\)</span>  For a tail multi-index <span class=\"process-math\">\\(\\mu=(\\mu_n)_{n&gt;N}\\in\\mathbf N^{(\\{n&gt;N\\})}\\text{,}\\)</span> write <span class=\"process-math\">\\(\\mu_n=2q_n+\\epsilon_n\\)</span> with <span class=\"process-math\">\\(\\epsilon_n\\in\\{0,1\\}\\)</span> and put</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\ne_\\mu=\\prod_{n&gt;N}Y_n^{\\epsilon_n}Z_n^{q_n}.\\tag{7.21}\n\\end{equation}\n</div>\n<div class=\"para\">The finite-stage normal forms give an isometric Banach-module decomposition</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\n\\mathcal A\\cong\n\\widehat{\\bigoplus}_{\\mu}^{\\,c_0}\\mathcal A_Ne_\\mu.\\tag{7.22}\n\\end{equation}\n</div>\n<div class=\"para\">Multiplication is determined by</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\ne_\\mu e_\\lambda\n=W^{\\omega(\\mu)+\\omega(\\lambda)-\\omega(\\mu+\\lambda)}e_{\\mu+\\lambda}.\\tag{7.23}\n\\end{equation}\n</div>\n<div class=\"para\">Here <span class=\"process-math\">\\(\\omega\\)</span> is applied only to the tail coordinates.  Projection to the coefficient of <span class=\"process-math\">\\(e_0\\)</span> is a norm-nonincreasing algebra retraction</div>\n<div class=\"displaymath process-math\">\n\\begin{equation}\n\\rho_N:\\mathcal A\\longrightarrow\\mathcal A_N.\\tag{7.24}\n\\end{equation}\n</div>\n<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-rationally-reduced-finite-head-rational-localization-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-formalisation": {"label": "Appendix A", "title": "Lean formalisation and verification", "html": "<div class=\"para\">This appendix concerns the finite-jet construction of <a href=\"#thm-main\" class=\"xref\" title=\"Theorem 1.1\">Theorem 1.1</a>; the weighted-parity construction of <a href=\"#sec-rationally-reduced\" class=\"internal\" title=\"Section 7: A rationally stably reduced example\">Section 7</a> has not yet been formalised.  Rather than reproduce the proofs, we record the three definitions which are most useful for comparing the formal statement with the mathematics in the paper.  The complete development is pinned to <a class=\"external\" href=\"https://github.com/CBirkbeck/AINTLIB/commit/b007a4f3d4226f00a684b402715aa542e2f0bcdc\" target=\"_blank\">commit <code class=\"code-inline tex2jax_ignore\">b007a4f3d</code></a> of AINTLIB.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-formalisation-2-1\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-formalisation-sheafiness": {"label": "Subsection A.1", "title": "Sheafiness", "html": "<div class=\"para\">For an open subset <span class=\"process-math\">\\(V\\subseteq\\Spa(A,A^+)\\text{,}\\)</span> the type <code class=\"code-inline tex2jax_ignore\">limitSections V</code> is the projective limit of the sections over the rational subdomains contained in <span class=\"process-math\">\\(V\\text{.}\\)</span>  The all-open sheaf condition is formalised as follows; the source is <a class=\"external\" href=\"https://github.com/CBirkbeck/AINTLIB/blob/b007a4f3d4226f00a684b402715aa542e2f0bcdc/projects/AdicSpaces/Adic%20spaces/SheafyPair.lean\" target=\"_blank\"><code class=\"code-inline tex2jax_ignore\">SheafyPair.lean</code></a>.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-formalisation-sheafiness-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-formalisation-strong-noetherianity": {"label": "Subsection A.2", "title": "Strong noetherianity", "html": "<div class=\"para\">The formal definition first constructs the restricted power-series ring.  A coefficient function tends to zero along the cofinite filter exactly when, for every neighbourhood of zero, all but finitely many coefficients belong to that neighbourhood.  The definitions below are from <a class=\"external\" href=\"https://github.com/CBirkbeck/AINTLIB/blob/b007a4f3d4226f00a684b402715aa542e2f0bcdc/projects/AdicSpaces/Adic%20spaces/RestrictedPowerSeries.lean\" target=\"_blank\"><code class=\"code-inline tex2jax_ignore\">RestrictedPowerSeries.lean</code></a>.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-formalisation-strong-noetherianity-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}, "sec-formalisation-the-finite-jet-example": {"label": "Subsection A.3", "title": "The finite-jet example", "html": "<div class=\"para\">We finally record the definition of the example itself.  In the following code, <code class=\"code-inline tex2jax_ignore\">PowerSeries.Restricted R 1</code> is the radius-one Tate algebra in one variable over <span class=\"process-math\">\\(R\\text{,}\\)</span> <code class=\"code-inline tex2jax_ignore\">RestrictedLaurent K</code> is <span class=\"process-math\">\\(K\\langle W,W^{-1}\\rangle\\text{,}\\)</span> and <code class=\"code-inline tex2jax_ignore\">DualNumber R</code> is <span class=\"process-math\">\\(R[Q]/(Q^2)\\text{.}\\)</span> The source is <a class=\"external\" href=\"https://github.com/CBirkbeck/AINTLIB/blob/b007a4f3d4226f00a684b402715aa542e2f0bcdc/projects/AdicSpaces/Adic%20spaces/FJP/Over/JetRings.lean\" target=\"_blank\"><code class=\"code-inline tex2jax_ignore\">FJP/Over/JetRings.lean</code></a>.<div class=\"autopermalink\" aria-hidden=\"true\" data-description=\"Paragraph\"><a tabindex=\"-1\" href=\"#sec-formalisation-the-finite-jet-example-2\" title=\"Copy heading and permalink for Paragraph\" aria-label=\"Copy heading and permalink for Paragraph\">🔗</a></div>\n</div>\n"}};
/* PreTeXt UI layer.
   (1) A global detail slider that reveals detail tiers by level.
   (2) Notation hovers that reveal a definition without a knowl underline
       (event-delegated, so lazily-typeset math is covered).
   (3) Proof-local "details" button that expands the proof text in place.
   (4) Contents sidebar hidden on page load. */
(function () {
  "use strict";

  // --- Notation registry. Generated per-instance from the document's
  //     <notation> list (single source of truth). Entry formats:
  //       key: "definition html"                          (no context link)
  //       key: {html: "...", href: "sec-x.html#def-id"}   (with context link)
  var NOTATION = window.PAPERFORGE_NOTATION || {};

  // Hover delays (ms). A far-marked symbol (.ptxfar wrapper, see
  // ingest/notation_far.py) waits FAR_DELAY before showing its definition;
  // near symbols show promptly. Override via window.paperforgeNotation.
  var CFG = window.paperforgeNotation || {};
  var FAR_DELAY_MS = CFG.farDelayMs != null ? CFG.farDelayMs : 1000;
  var NEAR_DELAY_MS = CFG.nearDelayMs != null ? CFG.nearDelayMs : 150;

  function ready(fn) {
    if (document.readyState !== "loading") fn();
    else document.addEventListener("DOMContentLoaded", fn);
  }

  function levelOf(el) {
    var m = /\bdetail-level-(\d+)\b/.exec(el.className);
    return m ? +m[1] : 0;
  }

  // Jump to #frag WITHOUT engaging the browser's :target styling (the theme
  // flashes the whole target block for 10s), then paint the specific
  // referenced element — occEl when given, else the target's heading — and
  // fade it out over five seconds.
  function landingGo(frag, occEl) {
    var target = document.getElementById(frag);
    if (!target) return false;
    var hl = occEl || target.querySelector(".heading") || target;
    (occEl || target).scrollIntoView(occEl ? {block: "center"}
                                           : {block: "start"});
    if (window.history && history.pushState) {
      history.pushState(null, "", "#" + frag);
    }
    hl.classList.remove("pf-landing-fade");
    hl.classList.add("pf-landing-hl");
    void hl.offsetWidth;                      // commit the painted state
    hl.classList.add("pf-landing-fade");
    setTimeout(function () {
      hl.classList.remove("pf-landing-hl", "pf-landing-fade");
    }, 5200);
    return true;
  }

  // Reveal machinery: tier elements are either born-hidden <details> knowls
  // (opened directly) or inline blocks like <p detail-level="2"> (revealed by
  // a `show-dl-N` class on a container — body for the global slider, the
  // proof element for the local button; CSS does the rest).
  function setTierClasses(container, level) {
    for (var l = 1; l <= 9; l++) {
      container.classList.toggle("show-dl-" + l, l <= level);
    }
  }

  // Header controls, mounted in the sticky navbar:
  //   Detail [range] n/max [manual]   [?]
  // Level 0 = everything collapsed, terse statements; level 1 = proofs and
  // remark knowls open + statement detail tiers (detail-level="1");
  // level 2+ = woven proof detail-tier paragraphs. "manual" replays the
  // reader's own open/close choices (recorded continuously, in localStorage).
  // [?] toggles notation links for readers who find the hovers distracting.
  var LS = {
    mode: "pf-detail-mode",            // "manual" | "0".."9"
    manual: "pf-detail-manual",        // {elementId: open?}
    notn: "pf-notation-off",           // "1" | absent
  };
  function lsGet(k, dflt) {
    try { var v = localStorage.getItem(k); return v === null ? dflt : v; }
    catch (e) { return dflt; }
  }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }

  function buildHeaderControls() {
    var tiers = Array.prototype.slice.call(
      document.querySelectorAll('[class*="detail-level-"]'));
    var knowls = Array.prototype.slice.call(
      document.querySelectorAll("details.born-hidden-knowl"));
    if (!tiers.length && !knowls.length) return;
    var max = tiers.reduce(function (a, d) { return Math.max(a, levelOf(d)); },
                           knowls.length ? 1 : 0);

    var bar = document.querySelector(".ptx-navbar-contents") ||
              document.querySelector("#ptx-navbar") || document.body;
    var wrap = document.createElement("div");
    wrap.className = "detail-ctl";
    wrap.innerHTML =
      '<label for="detail-range">Detail</label>' +
      '<input id="detail-range" type="range" min="0" max="' + max +
      '" value="0" step="1" title="0 = collapsed, 1 = proofs, higher = more">' +
      '<span class="detail-val">0/' + max + '</span>' +
      '<button type="button" class="detail-manual" title="replay your own ' +
      'open/close choices (remembered between visits)">manual</button>' +
      '<button type="button" class="notn-toggle" title="notation links ' +
      'on/off">?</button>';
    bar.appendChild(wrap);

    var range = wrap.querySelector("input");
    var out = wrap.querySelector(".detail-val");
    var manualBtn = wrap.querySelector(".detail-manual");
    var notnBtn = wrap.querySelector(".notn-toggle");

    var memory = {};
    try { memory = JSON.parse(lsGet(LS.manual, "{}")); } catch (e) {}

    function applyLevel(t) {
      out.textContent = t + "/" + max;
      knowls.forEach(function (d) { d.open = t >= 1; });
      tiers.forEach(function (d) {
        if (d.tagName === "DETAILS") d.open = levelOf(d) <= t;
      });
      setTierClasses(document.body, t);
    }
    function applyManual() {
      out.textContent = "–/" + max;
      Object.keys(memory).forEach(function (id) {
        var el = document.getElementById(id);
        if (el && el.tagName === "DETAILS") el.open = !!memory[id];
      });
    }
    function setMode(mode) {
      lsSet(LS.mode, mode);
      manualBtn.classList.toggle("active", mode === "manual");
      if (mode === "manual") applyManual();
      else { range.value = mode; applyLevel(+mode); }
    }

    // reader open/close choices are remembered — recorded from the actual
    // gesture (a click on a <summary>), because 'toggle' events also fire,
    // on an unpredictable schedule, for the slider's programmatic sweeps
    document.addEventListener("click", function (e) {
      var sum = e.target.closest && e.target.closest("summary");
      if (!sum || e.target.closest(".detail-next-btn")) return;
      var d = sum.parentElement;
      if (!d || d.tagName !== "DETAILS" || !d.id) return;
      setTimeout(function () {         // after the default toggle applied
        memory[d.id] = d.open;
        lsSet(LS.manual, JSON.stringify(memory));
      }, 0);
    });

    range.addEventListener("input", function () { setMode(range.value); });
    manualBtn.addEventListener("click", function () { setMode("manual"); });

    function setNotn(off) {
      document.body.classList.toggle("notation-links-off", off);
      notnBtn.classList.toggle("off", off);
      notnBtn.title = "notation links " + (off ? "off — click to enable"
                                               : "on — click to disable");
      lsSet(LS.notn, off ? "1" : "");
    }
    notnBtn.addEventListener("click", function () {
      setNotn(!document.body.classList.contains("notation-links-off"));
    });

    setNotn(lsGet(LS.notn, "") === "1");
    setMode(lsGet(LS.mode, "0"));
  }

  // Proof-local details: a small button on the "Proof" line (visible only
  // while the proof is open) steps the proof's own tiers up and back down —
  // the proof text expands in place.
  function wireProofDetails() {
    var proofs = Array.prototype.slice.call(
      document.querySelectorAll("details.hiddenproof"));
    proofs.forEach(function (proof) {
      var tiers = Array.prototype.slice.call(
        proof.querySelectorAll('[class*="detail-level-"]'));
      if (!tiers.length) return;
      var levels = [];
      tiers.forEach(function (d) {
        var l = levelOf(d);
        if (levels.indexOf(l) < 0) levels.push(l);
      });
      levels.sort(function (a, b) { return a - b; });
      var summary = proof.querySelector("summary");
      if (!summary) return;
      var btn = document.createElement("button");
      btn.className = "detail-next-btn";
      summary.appendChild(btn);
      var cur = 0;
      function nextLevel() {
        for (var i = 0; i < levels.length; i++)
          if (levels[i] > cur) return levels[i];
        return null;
      }
      function label() {
        btn.textContent = nextLevel() ? "▸ details" : "▾ less";
      }
      btn.addEventListener("click", function (e) {
        e.preventDefault();      // do not toggle the enclosing summary
        e.stopPropagation();
        var nxt = nextLevel();
        cur = nxt !== null ? nxt : 0;
        setTierClasses(proof, cur);
        tiers.forEach(function (d) {
          if (d.tagName === "DETAILS") d.open = levelOf(d) <= cur;
        });
        label();
      });
      label();
    });
  }

  // Statement-local details: a theorem-like block whose STATEMENT carries
  // tier paragraphs (detail-level="1") gets the same stepper as proofs,
  // placed just before the first hidden tier — the terse statement expands
  // in place. (PreTeXt emits no statement wrapper in HTML: statement
  // paragraphs are direct article children; proof tiers live inside the
  // reparented <details> and are excluded.)
  function wireStatementDetails() {
    var arts = Array.prototype.slice.call(
      document.querySelectorAll("article.theorem-like, " +
        "article.definition-like, article.remark-like"));
    arts.forEach(function (art) {
      var tiers = Array.prototype.slice.call(
        art.querySelectorAll('[class*="detail-level-"]')).filter(
          function (d) { return !d.closest("details"); });
      if (!tiers.length) return;
      var levels = [];
      tiers.forEach(function (d) {
        var l = levelOf(d);
        if (levels.indexOf(l) < 0) levels.push(l);
      });
      levels.sort(function (a, b) { return a - b; });
      var btn = document.createElement("button");
      btn.className = "detail-next-btn detail-stmt-btn";
      tiers[0].insertAdjacentElement("beforebegin", btn);
      var cur = 0;
      function nextLevel() {
        for (var i = 0; i < levels.length; i++)
          if (levels[i] > cur) return levels[i];
        return null;
      }
      function label() {
        btn.textContent = nextLevel() ? "▸ details" : "▾ less";
      }
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var nxt = nextLevel();
        cur = nxt !== null ? nxt : 0;
        setTierClasses(art, cur);
        label();
      });
      label();
    });
  }

  // Contents visible by default on wide screens (owner request 2026-07-27,
  // reversing the earlier hide-on-load): the default-open rule lives in
  // paper-style.css; the theme's toggle adds .hidden/.visible as before.

  // Notation hovers, event-delegated: works regardless of when MathJax
  // typesets a given expression (required for lazy typesetting, where math
  // renders as it scrolls into view).
  function wireNotation() {
    var pop = document.createElement("div");
    pop.className = "notation-popup";
    document.body.appendChild(pop);
    var hideTimer, showTimer, hlTimer, hoverEl = null, hlTarget = null;
    var DEFSITE_HL_MS = CFG.defsiteHlDelayMs != null ? CFG.defsiteHlDelayMs : 120;

    pop.addEventListener("mouseenter", function () { clearTimeout(hideTimer); });
    pop.addEventListener("mouseleave", scheduleHide);

    // Following a context link: instead of the theme's whole-block :target
    // flash, jump there and paint ONLY the specific referenced text — the
    // defining occurrence of the term when the target block carries one,
    // else the target's heading (landingGo).
    pop.addEventListener("click", function (e) {
      var a = e.target.closest ? e.target.closest(".notation-ctx-link") : null;
      if (!a) return;
      if (e.metaKey || e.ctrlKey || e.shiftKey) return;   // allow new-tab
      var href = a.getAttribute("href") || "";
      var i = href.indexOf("#");
      if (i < 0) return;
      var page = href.slice(0, i).split("/").pop();
      if (page && page !== location.pathname.split("/").pop()) return;
      var occ = pop._entry ? defOccurrence(pop._entry, pop._key) : null;
      if (!landingGo(href.slice(i + 1), occ)) return;
      e.preventDefault();
      pop.classList.remove("show");
      clearMarks();
    });

    function keyOf(el) {
      var m = /\bptxnotn-([A-Za-z0-9]+)\b/.exec(el.className);
      return m ? m[1] : null;
    }
    function entryFor(k) {
      var v = NOTATION[k];
      if (!v) return null;
      return typeof v === "string" ? { html: v, href: null } : v;
    }
    function isFar(el) {
      return !!(el.closest && el.closest(".ptxfar"));
    }
    function defsiteEl(entry) {
      if (!entry || !entry.href) return null;
      var i = entry.href.indexOf("#");
      return i >= 0 ? document.getElementById(entry.href.slice(i + 1)) : null;
    }
    // The DEFINING OCCURRENCE of a key: the first wrapped occurrence of
    // exactly this key inside its defsite block. This is what hovering
    // elsewhere highlights (a symbol-sized area, never a whole block),
    // and hovering it is what flips the cursor to the ≝ affordance.
    function defOccurrence(entry, k) {
      var target = defsiteEl(entry);
      if (!target) return null;
      var cands = target.querySelectorAll('[class*="ptxnotn-"]');
      for (var i = 0; i < cands.length; i++) {
        if (keyOf(cands[i]) === k) return cands[i];
      }
      return null;
    }
    function show(el) {
      var k = keyOf(el);
      var entry = k && entryFor(k);
      if (!entry) return;
      clearTimeout(hideTimer);
      // prose/background entries carry a human heading; math keys ARE one
      var html = '<span class="notation-popup-key">' + (entry.label || k) +
                 '</span>' + entry.html;
      if (entry.href) {
        // terminology entries (entry.more) point at the background block
        // that reviews the notion; notation entries at the defining spot
        var label = entry.more ? "more details" : "see definition in context";
        html += '<a class="notation-ctx-link" href="' + entry.href +
                '">' + label + ' &#x2197;</a>';
      }
      pop.innerHTML = html;
      pop._key = k;                 // for the context-link landing highlight
      pop._entry = entry;
      var r = el.getBoundingClientRect();
      // Place BELOW the symbol so the popup never covers the text being read.
      pop.style.top = (window.scrollY + r.bottom + 6) + "px";
      pop.style.left = (window.scrollX + r.left) + "px";
      pop.classList.add("show");
      if (window.MathJax && MathJax.typesetPromise) {
        MathJax.typesetPromise([pop]).catch(function () {});
      }
    }
    function clearMarks() {
      clearTimeout(hlTimer);
      if (hlTarget) { hlTarget.classList.remove("notation-defsite-hl"); hlTarget = null; }
    }
    function scheduleHide() {
      clearTimeout(showTimer);
      hideTimer = setTimeout(function () {
        pop.classList.remove("show");
        clearMarks();
      }, 180);
    }

    document.addEventListener("mouseover", function (e) {
      if (document.body.classList.contains("notation-links-off")) return;
      var el = e.target.closest
        ? e.target.closest('[class*="ptxnotn-"]') : null;
      if (el === hoverEl) return;
      if (el) {
        hoverEl = el;
        clearTimeout(hideTimer);
        clearTimeout(showTimer);
        clearMarks();
        var k = keyOf(el);
        var entry = k && entryFor(k);
        var defEl = defOccurrence(entry, k);
        var atDef = !!(defEl && (defEl === el || defEl.contains(el) ||
                                 el.contains(defEl)));
        if (atDef) {
          // this IS the definition: no popup, no highlight — the cursor
          // itself becomes the "source of the notation" affordance
          el.classList.add("notation-defcursor");
          el.title = "this defines " + k;
          return;
        }
        // the defining occurrence (a symbol-sized area) lights up a beat
        // before the popup — just enough delay to skip a passing mouse
        hlTimer = setTimeout(function () {
          if (defEl) {
            defEl.classList.add("notation-defsite-hl");
            hlTarget = defEl;
          }
        }, DEFSITE_HL_MS);
        // prose term links (.ptxbg) read like ordinary text, so they get
        // the far delay: no popup flicker while mousing across a paragraph
        var far = isFar(el) || (el.classList && el.classList.contains("ptxbg"));
        var delay = far ? FAR_DELAY_MS : NEAR_DELAY_MS;
        showTimer = setTimeout(function () { show(el); }, delay);
      } else if (hoverEl && !(e.target.closest &&
                              e.target.closest(".notation-popup"))) {
        hoverEl = null;
        scheduleHide();
      }
    });
  }

  // Equation ranges: "(1.1)–(1.3)" is authored as two equation xrefs around
  // an en dash, so only the endpoints open as knowls. Make the whole range
  // ONE click target that opens every equation in the range — endpoints and
  // middles alike — in a single stacked panel. Content is re-typeset from
  // MathJax's stored TeX (getMathItemsWithin), so it works even for middle
  // equations that were never cross-referenced (no knowl file) or not yet
  // lazily typeset; \notn wrappers survive, so notation hovers work inside.
  function wireEquationRanges() {
    function eqTarget(a) {
      var href = a.getAttribute("href") || "";
      if (href.charAt(0) !== "#") return null;
      var el = document.getElementById(href.slice(1));
      return el && el.classList.contains("displaymath") ? el : null;
    }
    function eqNum(a) {   // "(1.3)" -> {prefix: "1.", n: 3}
      var m = /^\((?:([0-9A-Za-z.]+)\.)?(\d+)\)$/.exec(a.textContent.trim());
      return m ? {prefix: m[1] ? m[1] + "." : "", n: +m[2]} : null;
    }
    var anchors = Array.prototype.slice.call(
      document.querySelectorAll('.ptx-content a[data-knowl][href^="#"]'));
    anchors.forEach(function (a1) {
      var dash = a1.nextSibling;
      if (!dash || dash.nodeType !== 3 ||
          dash.textContent.trim() !== "–") return;
      var a2 = dash.nextSibling;
      if (!a2 || a2.nodeType !== 1 ||
          !a2.matches('a[data-knowl][href^="#"]')) return;
      var e1 = eqTarget(a1), e2 = eqTarget(a2);
      var n1 = eqNum(a1), n2 = eqNum(a2);
      if (!e1 || !e2 || !n1 || !n2) return;
      if (n1.prefix !== n2.prefix || n2.n <= n1.n) return;
      var all = Array.prototype.slice.call(
        document.querySelectorAll("div.displaymath[id]"));
      var i1 = all.indexOf(e1), i2 = all.indexOf(e2);
      if (i1 < 0 || i2 <= i1) return;
      var eqs = all.slice(i1, i2 + 1);
      if (eqs.length !== n2.n - n1.n + 1) return;  // numbering mismatch: bail
      var span = document.createElement("span");
      span.className = "eqrange";
      span.title = "show equations " + a1.textContent + "–" +
                   a2.textContent;
      a1.parentNode.insertBefore(span, a1);
      span.appendChild(a1);
      span.appendChild(dash);
      span.appendChild(a2);
      span.addEventListener("click", function (e) {
        if (e.metaKey || e.ctrlKey || e.shiftKey) return;   // allow new-tab
        e.preventDefault();
        e.stopPropagation();
        if (span._panel && span._panel.isConnected) {
          span._panel.remove();
          span._panel = null;
          return;
        }
        var doc = window.MathJax && MathJax.startup && MathJax.startup.document;
        var parts = eqs.map(function (eq) {
          var tex = null;
          if (doc && doc.getMathItemsWithin) {
            var items = doc.getMathItemsWithin(eq);
            if (items.length === 1) tex = items[0].math;
          }
          if (tex == null) return null;
          // the stored TeX carries its own \tag{...} (the printed number);
          // strip only the environment and any \label (re-typesetting a
          // duplicate label is a MathJax error)
          tex = tex.replace(/\\begin\{equation\*?\}|\\end\{equation\*?\}/g, "")
                   .replace(/\\label\{[^{}]*\}/g, "");
          return "\\[" + tex + "\\]";
        });
        if (parts.indexOf(null) >= 0) {
          a1.click();          // stored TeX unavailable: at least open the
          a2.click();          // endpoint knowls the classical way
          return;
        }
        var panel = document.createElement("div");
        panel.className = "eqrange-knowl";
        panel.innerHTML = parts.join("\n");
        var foot = document.createElement("div");
        foot.className = "eqrange-knowl-foot";
        var ctx = document.createElement("a");
        ctx.href = "#" + e1.id;
        ctx.textContent = "view in context ↗";
        ctx.addEventListener("click", function (ev) {
          if (ev.metaKey || ev.ctrlKey || ev.shiftKey) return;
          ev.preventDefault();
          ev.stopPropagation();
          panel.remove();
          span._panel = null;
          landingGo(e1.id, e1);
        });
        foot.appendChild(ctx);
        panel.appendChild(foot);
        var host = span.closest(".para, li, .knowl__content") || span;
        host.insertAdjacentElement("afterend", panel);
        span._panel = panel;
        if (window.MathJax && MathJax.typesetPromise) {
          MathJax.typesetPromise([panel]).catch(function () {});
        }
      }, true);      // capture: beat the anchors' own knowl handlers
    });
  }

  // Lean badges open the declaration's doc entry inline, knowl-style, when
  // the build-time registry (lean-knowls.js) has it; otherwise (or on
  // modified click) they navigate to the docs as plain links.
  function wireLeanKnowls() {
    var REG = window.PAPERFORGE_LEAN_KNOWLS || {};
    // The registry is generated FROM the built docs, so when it is present
    // a badge it lacks has no doc page (private decl, doc-gen4 gap): its
    // find-resolver link would 404. Degrade those to inert pills. Without
    // a registry we cannot tell, so links are left alone.
    if (window.PAPERFORGE_LEAN_KNOWLS) {
      document.querySelectorAll("a.lean-link").forEach(function (a) {
        if (REG[a.getAttribute("data-lean-ref")]) return;
        a.removeAttribute("href");
        a.classList.add("lean-nolink");
        a.title += " (no documentation page)";
      });
    }
    document.addEventListener("click", function (e) {
      var a = e.target.closest ? e.target.closest("a.lean-link") : null;
      if (!a) return;
      var entry = REG[a.getAttribute("data-lean-ref")];
      if (!entry) return;
      if (e.metaKey || e.ctrlKey || e.shiftKey) return;   // allow new-tab
      e.preventDefault();
      if (a._leanKnowl) {
        a._leanKnowl.remove();
        a._leanKnowl = null;
        a.setAttribute("aria-expanded", "false");
        return;
      }
      var panel = document.createElement("div");
      panel.className = "lean-knowl";
      panel.setAttribute("role", "region");
      panel.setAttribute("aria-label",
        "Lean declaration " + a.getAttribute("data-lean-ref"));
      panel.innerHTML = entry.html +
        '<div class="lean-knowl-foot"><a href="' + entry.href +
        '">full documentation ↗</a></div>';
      a.insertAdjacentElement("afterend", panel);
      a._leanKnowl = panel;
      a.setAttribute("aria-expanded", "true");
      if (window.MathJax && MathJax.typesetPromise) {
        MathJax.typesetPromise([panel]).catch(function () {});
      }
    });
  }

  // Cross-references to divisions (Section 5, Subsection A.4, ...) open the
  // division's summary in place, knowl-style, from the build-time registry
  // (section-summaries.js): leading prose + a view-in-context link. TOC and
  // in-popup navigation links keep navigating; so do divisions the registry
  // lacks (no leading prose) and modified clicks.
  function wireSectionSummaries() {
    var REG = window.PAPERFORGE_SECTION_SUMMARIES;
    if (!REG) return;
    document.addEventListener("click", function (e) {
      if (e.target.closest && e.target.closest(".section-knowl-foot")) {
        e.target.closest(".section-knowl").remove();   // navigate + tidy up
        return;
      }
      var a = e.target.closest ? e.target.closest('a.internal[href^="#"]') : null;
      if (!a || a.hasAttribute("data-knowl")) return;
      if (!a.closest(".ptx-content")) return;          // TOC, masthead
      if (a.closest(".section-knowl, .notation-popup")) return;
      var tag = a.getAttribute("href").slice(1);
      var entry = REG[tag];
      if (!entry) return;
      if (e.metaKey || e.ctrlKey || e.shiftKey) return;   // allow new-tab
      e.preventDefault();
      if (a._secKnowl && a._secKnowl.isConnected) {
        a._secKnowl.remove();
        a._secKnowl = null;
        a.setAttribute("aria-expanded", "false");
        return;
      }
      var panel = document.createElement("div");
      panel.className = "section-knowl";
      panel.setAttribute("role", "region");
      panel.setAttribute("aria-label", entry.label +
        (entry.title ? ": " + entry.title : ""));
      panel.innerHTML =
        '<div class="section-knowl-title">' + entry.label +
        (entry.title ? " · " + entry.title : "") + "</div>" +
        entry.html +
        '<div class="section-knowl-foot"><a href="#' + tag +
        '">view in context ↗</a></div>';
      var host = a.closest(".para, li, .knowl__content") || a;
      host.insertAdjacentElement("afterend", panel);
      a._secKnowl = panel;
      a.setAttribute("aria-expanded", "true");
      if (window.MathJax && MathJax.typesetPromise) {
        MathJax.typesetPromise([panel]).catch(function () {});
      }
    });
  }

  // Publication links injected into the one-page PreTeXt build.
  function addHomeLinks() {
    var masthead = document.querySelector('.ptx-masthead .title-container');
    if (masthead && !masthead.querySelector('.site-home-link')) {
      var top = document.createElement('div');
      top.className = 'site-home-link';
      top.innerHTML =
        '<a href="paper.pdf">PDF</a> · ' +
        '<a href="https://github.com/CBirkbeck/uniform-sheafy-tate-domains">' +
        'Source repository</a>';
      masthead.appendChild(top);
    }
    var host = document.querySelector('.ptx-content-footer') ||
               document.querySelector('.ptx-main') || document.body;
    if (!host.querySelector('.site-home-return')) {
      var bottom = document.createElement('div');
      bottom.className = 'site-home-return';
      bottom.innerHTML =
        '<a href="paper.pdf">Download the PDF</a> · ' +
        '<a href="https://github.com/CBirkbeck/uniform-sheafy-tate-domains">' +
        'View the source repository</a>.';
      host.appendChild(bottom);
    }
  }

  ready(function () {
    buildHeaderControls();
    wireProofDetails();
    wireStatementDetails();
    wireNotation();
    wireEquationRanges();
    wireLeanKnowls();
    wireSectionSummaries();
    addHomeLinks();
  });
})();
